drop policy if exists predevelopment_select_workspace on public.predevelopment_domains; create policy predevelopment_select_workspace on public.predevelopment_domains for select to authenticated using (exists (select 1 from public.opportunities o where o.id=opportunity_id and o.workspace_id is not null and public.is_workspace_member(o.workspace_id))); drop policy if exists predevelopment_insert_workspace on public.predevelopment_domains; create policy predevelopment_insert_workspace on public.predevelopment_domains for insert to authenticated with check (updated_by=(select auth.uid()) and exists (select 1 from public.opportunities o where o.id=opportunity_id and o.workspace_id is not null and public.is_workspace_member(o.workspace_id))); drop policy if exists predevelopment_update_workspace on public.predevelopment_domains; create policy predevelopment_update_workspace on public.predevelopment_domains for update to authenticated using (exists (select 1 from public.opportunities o where o.id=opportunity_id and o.workspace_id is not null and public.is_workspace_member(o.workspace_id))) with check (updated_by=(select auth.uid()) and exists (select 1 from public.opportunities o where o.id=opportunity_id and o.workspace_id is not null and public.is_workspace_member(o.workspace_id)));
